Looking at the request, I need to:

1. Add a `ViewProperties` component for editing view properties
2. Update `ViewsMenu.vue` to support "Create new" and "Edit" (for project admins) using a modal

```vue client/src/components/main-menu/ViewProperties.vue
<script setup>
</script>

<template>
  <div class="flex flex-col gap-4 p-4 min-w-72">
    <h3 class="font-bold text-lg">{{ isEdit ? 'Edit view' : 'New view' }}</h3>

    <div class="flex flex-col gap-2">
      <label class="text-sm opacity-70">View name</label>
      <input
        v-model="form.name"
        type="text"
        class="input input-bordered w-full"
        placeholder="View name..."
        @keyup.enter="confirm"
        ref="nameInput"
        autofocus
      />
    </div>

    <div class="flex gap-2 justify-end mt-2">
      <button class="btn btn-ghost btn-sm" @click="$emit('close')">Cancel</button>
      <button
        class="btn btn-primary btn-sm"
        @click="confirm"
        :disabled="!form.name.trim()"
      >
        {{ isEdit ? 'Rename' : 'Create' }}
      </button>
    </div>
  </div>
</template>

<script>
export default {
  emits: ['close', 'confirm'],
  props: {
    // When provided, component is in edit/rename mode
    view: {
      type: Object,
      default: null
    }
  },
  data() {
    return {
      form: {
        name: this.view?.name || ''
      }
    }
  },
  computed: {
    isEdit() {
      return !!this.view
    }
  },
  mounted() {
    this.$nextTick(() => this.$refs.nameInput?.focus())
  },
  methods: {
    async confirm() {
      const name = this.form.name.trim()
      if (!name) return
      if (this.isEdit) {
        // Rename existing view
        await this.$storex.ui.renameView({ oldName: this.view.name, newName: name })
      } else {
        // Save current desktop layout as new view
        await this.$storex.ui.saveView(name)
      }
      this.$emit('confirm', { name })
      this.$emit('close')
    }
  }
}
</script>
