    },
    isProjectAdmin() {
      return this.$storex.projects.activeProject?.permissions?.includes('admin') ||
        this.$storex.session.user?.role === 'admin'
    }
  },
  methods: {
    // Open modal in "create new view" mode
    openCreateModal() {
      this.editingView = null
      this.showModal = true
    },
