    <dockview-vue
      class="dockview-theme-abyss w-full h-full"
      @ready="onReady"
    />

    <!-- ViewProperties modal triggered by store viewEditor flag -->
    <div
      v-if="viewEditor"
      class="absolute inset-0 z-50 flex items-center justify-center bg-black/50"
      @click.self="closeViewEditor"
